public final class Order {                 // concept: identity, invariant, behaviour
    private final OrderId id;
    private OrderStatus status = OrderStatus.NEW;

    public void markAsPaid() {              // business operation, not a setter
        if (status != OrderStatus.NEW) throw new IllegalStateException(status.name());
        status = OrderStatus.PAID;
    }

    OrderId id() { return id; }             // package-private: inside the contour
}
